INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the purpose of periodic ''card clothing'' maintenance (grinding/sharpening the fine wire teeth on carding cylinders/flats)?', '["To maintain the sharpness and correct geometry of the wire teeth, ensuring effective fiber opening/individualization and consistent carding quality over time","To permanently remove all wire clothing from the machine","To add color/dye to the carded sliver directly at the card","To increase the machine''s electrical power consumption intentionally"]'::jsonb, 'To maintain the sharpness and correct geometry of the wire teeth, ensuring effective fiber opening/individualization and consistent carding quality over time', 'Card clothing wire teeth gradually dull and can become misaligned with use; periodic grinding restores sharp, correctly angled teeth needed for effective fiber opening/individualization — worn, unsharpened clothing leads to poor carding (more neps, uneven sliver).', 2, '{"card-clothing-maintenance"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What might happen to sliver/yarn quality if carding machine clothing is allowed to become excessively worn/dull without maintenance?', '["Increased neps, reduced fiber individualization, and poorer overall sliver/yarn evenness and quality","Sliver quality would automatically improve with worn/dull clothing","Worn clothing has no measurable effect on carding output quality","Carding would stop working entirely with any wear at all, with no gradual quality decline"]'::jsonb, 'Increased neps, reduced fiber individualization, and poorer overall sliver/yarn evenness and quality', 'As card clothing wears/dulls, its ability to properly open and separate fiber tufts into individual fibers declines, leading to more neps, poorer fiber alignment, and reduced overall sliver/yarn quality — a gradual decline that regular maintenance/grinding is meant to prevent.', 2, '{"worn-card-clothing"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the function of ''autoleveller'' technology at the draw frame?', '["It continuously measures the sliver''s thickness/mass and automatically adjusts the draft in real time to correct for detected irregularities","It permanently levels the floor beneath the draw frame machine","It only measures color, adjusting the dye recipe automatically","It replaces the need for any drafting rollers at the draw frame"]'::jsonb, 'It continuously measures the sliver''s thickness/mass and automatically adjusts the draft in real time to correct for detected irregularities', 'An autoleveller uses sensors to continuously monitor incoming sliver mass/thickness and automatically adjusts the draft ratio in real time, correcting for detected thick/thin variations and significantly improving long-term (and some short-term) count evenness compared to fixed-draft drawing.', 1, '{"autoleveller"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why is autoleveller technology particularly valuable at the LAST drawing passage before roving/spinning, rather than only at an earlier passage?', '["Correcting irregularities as close as possible to the final spinning stage minimizes the chance that new irregularities introduced downstream go uncorrected","Autolevellers can only physically be installed at the very first drawing passage, never the last","The last passage has no measurable impact on final yarn evenness compared to earlier passages","Autolevelling only affects fiber color, unrelated to any drafting stage''s position in the sequence"]'::jsonb, 'Correcting irregularities as close as possible to the final spinning stage minimizes the chance that new irregularities introduced downstream go uncorrected', 'While autolevelling can be applied at various passages, having it at the LAST drawing stage (closest to roving/spinning) is especially valuable since it''s the final opportunity to correct sliver irregularity before the material proceeds to roving and ring spinning, where such variation would otherwise directly translate into yarn count variation.', 2, '{"autoleveller-positioning"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the purpose of ''ring and traveler matching'' (selecting an appropriately sized/weighted traveler for a given ring diameter and yarn count) in ring spinning?', '["To balance yarn tension appropriately — enough to wind properly onto the bobbin without excessive end breakage from too much traveler drag","Ring and traveler size have no relationship to each other or to yarn tension at all","Traveler selection only affects the final yarn''s color, not its tension or breakage rate","A single universal traveler size works equally well for every yarn count and ring size"]'::jsonb, 'To balance yarn tension appropriately — enough to wind properly onto the bobbin without excessive end breakage from too much traveler drag', 'Selecting the right traveler weight/size for a given ring diameter and yarn count balances the tension needed to wind yarn properly onto the bobbin against the risk of excessive tension (from too heavy a traveler) causing increased end breakage — an important practical spinning parameter.', 2, '{"ring-traveler-matching"}'::text[]);
